import { useCallback, useEffect, useRef, useState } from 'react';
import {
  type AccessibilityActionEvent,
  Animated,
  type GestureResponderHandlers,
  type LayoutChangeEvent,
  PanResponder,
  StyleSheet,
  View,
} from 'react-native';

import { Text } from '@shared/ui/primitives/Text';
import { useTheme } from '@shared/ui/theme';
import { spacing } from '@shared/ui/theme/tokens';

const A11Y_SEEK_STEP_MS = 15000;

interface ScrubberProps {
  positionMs: number;
  durationMs: number;
  onSeek: (positionMs: number) => void;
}

function formatTime(ms: number): string {
  if (!Number.isFinite(ms) || ms < 0) return '0:00';
  const totalSeconds = Math.floor(ms / 1000);
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;
  return `${minutes}:${seconds.toString().padStart(2, '0')}`;
}

// Animated interpolation extrapolates past its input range, so any ratio fed to
// the progress value must stay inside [0, 1] or the fill/thumb overshoot the track.
function clampRatio(ratio: number): number {
  return Math.max(0, Math.min(1, ratio));
}

// Position and duration are independent native reads, so near the end of a track
// the position can briefly exceed the duration.
function progressRatio(positionMs: number, durationMs: number): number {
  return clampRatio(positionMs / durationMs);
}

function ratioFromPageX(pageX: number, layout: { pageX: number; width: number }): number {
  const x = pageX - layout.pageX;
  return clampRatio(x / (layout.width || 1));
}

export function Scrubber({ positionMs, durationMs, onSeek }: ScrubberProps) {
  const theme = useTheme();
  const trackRef = useRef<View>(null);
  const layoutRef = useRef({ pageX: 0, width: 0 });

  const durationRef = useRef(durationMs);
  const onSeekRef = useRef(onSeek);
  const positionRef = useRef(positionMs);

  // Keep the latest props reachable from the gesture callbacks without reading
  // or writing refs during render (react-hooks/refs).
  useEffect(() => {
    durationRef.current = durationMs;
    onSeekRef.current = onSeek;
    positionRef.current = positionMs;
  });

  const [progress] = useState(() => new Animated.Value(0));
  const isDraggingRef = useRef(false);
  const isHoldingSeek = useRef(false);
  const seekHoldTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const lastLabelUpdate = useRef(0);

  const [isDragging, setIsDragging] = useState(false);
  const [labelMs, setLabelMs] = useState(positionMs);

  useEffect(() => {
    if (!isDraggingRef.current && !isHoldingSeek.current && durationMs > 0) {
      progress.setValue(progressRatio(positionMs, durationMs));
      setLabelMs(positionMs);
    }
  }, [positionMs, durationMs, progress]);

  // Build the pan responder in an effect, not during render: passing its
  // ref-reading gesture callbacks into PanResponder.create() during render trips
  // react-hooks/refs. Inside an effect, reading refs and the clock is allowed;
  // its handlers reach the component through state read during render.
  const [panHandlers, setPanHandlers] = useState<GestureResponderHandlers>({});
  useEffect(() => {
    const responder = PanResponder.create({
      onStartShouldSetPanResponder: () => true,
      onMoveShouldSetPanResponder: () => true,
      onPanResponderTerminationRequest: () => false,
      // Until the duration is known every ratio maps to 0:00, so a drag in that
      // window must not move the thumb or seek (same guard as the a11y action).
      onPanResponderGrant: (evt) => {
        if (durationRef.current <= 0) return;
        isDraggingRef.current = true;
        setIsDragging(true);
        if (seekHoldTimer.current) {
          clearTimeout(seekHoldTimer.current);
          seekHoldTimer.current = null;
        }
        isHoldingSeek.current = false;
        const ratio = ratioFromPageX(evt.nativeEvent.pageX, layoutRef.current);
        progress.setValue(ratio);
        setLabelMs(ratio * durationRef.current);
        lastLabelUpdate.current = Date.now();
      },
      onPanResponderMove: (evt) => {
        if (durationRef.current <= 0) return;
        const ratio = ratioFromPageX(evt.nativeEvent.pageX, layoutRef.current);
        progress.setValue(ratio);
        const now = Date.now();
        if (now - lastLabelUpdate.current > 80) {
          lastLabelUpdate.current = now;
          setLabelMs(ratio * durationRef.current);
        }
      },
      onPanResponderRelease: (evt) => {
        isDraggingRef.current = false;
        setIsDragging(false);
        if (durationRef.current <= 0) return;
        const ratio = ratioFromPageX(evt.nativeEvent.pageX, layoutRef.current);
        const ms = ratio * durationRef.current;
        progress.setValue(ratio);
        setLabelMs(ms);
        onSeekRef.current(ms);
        isHoldingSeek.current = true;
        seekHoldTimer.current = setTimeout(() => {
          isHoldingSeek.current = false;
          if (durationRef.current > 0) {
            progress.setValue(progressRatio(positionRef.current, durationRef.current));
            setLabelMs(positionRef.current);
          }
        }, 600);
      },
      onPanResponderTerminate: () => {
        isDraggingRef.current = false;
        setIsDragging(false);
        isHoldingSeek.current = false;
        if (seekHoldTimer.current) {
          clearTimeout(seekHoldTimer.current);
          seekHoldTimer.current = null;
        }
      },
    });
    setPanHandlers(responder.panHandlers);
    return () => {
      if (seekHoldTimer.current) {
        clearTimeout(seekHoldTimer.current);
        seekHoldTimer.current = null;
      }
    };
  }, [progress]);

  const remeasure = useCallback(() => {
    trackRef.current?.measureInWindow((x, _y, width) => {
      if (width > 0) layoutRef.current = { pageX: x, width };
    });
  }, []);

  const onLayout = useCallback(
    (_e: LayoutChangeEvent) => {
      remeasure();
    },
    [remeasure],
  );

  const onAccessibilityAction = useCallback((e: AccessibilityActionEvent) => {
    const dur = durationRef.current;
    if (dur <= 0) return;
    const delta = e.nativeEvent.actionName === 'decrement' ? -A11Y_SEEK_STEP_MS : A11Y_SEEK_STEP_MS;
    const next = Math.max(0, Math.min(dur, positionRef.current + delta));
    onSeekRef.current(next);
  }, []);

  const fillWidth = progress.interpolate({
    inputRange: [0, 1],
    outputRange: ['0%', '100%'],
  });
  const thumbLeft = progress.interpolate({
    inputRange: [0, 1],
    outputRange: ['0%', '100%'],
  });

  return (
    <View style={styles.container}>
      <View
        ref={trackRef}
        style={styles.trackOuter}
        onLayout={onLayout}
        accessibilityRole="adjustable"
        accessibilityLabel={`Playback position: ${formatTime(labelMs)} of ${formatTime(durationMs)}`}
        accessibilityValue={{
          min: 0,
          max: 100,
          now: Math.round(durationMs > 0 ? (labelMs / durationMs) * 100 : 0),
        }}
        accessibilityActions={[{ name: 'increment' }, { name: 'decrement' }]}
        onAccessibilityAction={onAccessibilityAction}
        {...panHandlers}
      >
        <View style={[styles.trackBg, { backgroundColor: theme.color.border }]} />
        <Animated.View
          style={[styles.trackFill, { width: fillWidth, backgroundColor: theme.color.accent }]}
        />
        <Animated.View
          style={[
            styles.thumb,
            {
              left: thumbLeft,
              backgroundColor: theme.color.accent,
              transform: [{ scale: isDragging ? 1.3 : 1 }],
            },
          ]}
        />
      </View>
      <View style={styles.times}>
        <Text variant="caption" tone="secondary">
          {formatTime(durationMs > 0 ? labelMs : positionMs)}
        </Text>
        <Text variant="caption" tone="secondary">
          {durationMs > 0 ? `-${formatTime(Math.max(0, durationMs - labelMs))}` : ''}
        </Text>
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    width: '100%',
    paddingHorizontal: spacing['2xl'],
  },
  trackOuter: {
    height: 44,
    justifyContent: 'center',
  },
  trackBg: {
    position: 'absolute',
    left: 0,
    right: 0,
    height: 3,
    borderRadius: 1.5,
  },
  trackFill: {
    position: 'absolute',
    left: 0,
    height: 3,
    borderRadius: 1.5,
  },
  thumb: {
    position: 'absolute',
    width: 14,
    height: 14,
    borderRadius: 7,
    marginLeft: -7,
    top: 15,
  },
  times: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    marginTop: spacing.xs,
  },
});
